import { BooleanColumn, IntegerColumn, ReferenceColumn, Table, StringColumn } from '../../db'

export const sys_ux_screen = Table({
    name: 'sys_ux_screen',
    schema: {
        name: StringColumn({}),
        order: IntegerColumn({}),
        active: BooleanColumn({}),
        app_config: ReferenceColumn({ referenceTable: 'sys_ux_app_config' }),
        description: StringColumn({}),
        disable_auto_reflow: BooleanColumn({}),
        event_mappings: StringColumn({}),
        macroponent: ReferenceColumn({ referenceTable: 'sys_ux_macroponent' }),
        macroponent_config: StringColumn({}),
        parent_macroponent: StringColumn({}), // TODO: Self reference?
        required_translations: StringColumn({}),
        screen_type: ReferenceColumn({ referenceTable: 'sys_ux_screen_type' }),
    },
})
